from datetime import datetime

def parse_year(release_date_str):
    if not release_date_str:
        return None
    try:
        return datetime.fromisoformat(release_date_str.replace('Z','+00:00')).year
    except Exception:
        try:
            return int(str(release_date_str)[:4])
